package com.master.bedtime.child;

import android.content.Context;import android.graphics.PixelFormat;import android.provider.Settings;import android.view.Gravity;import android.view.LayoutInflater;import android.view.View;import android.view.WindowManager;
public final class BedtimeOverlay { private static View view; public static synchronized void show(Context context){if(view!=null||!Settings.canDrawOverlays(context))return;WindowManager wm=(WindowManager)context.getSystemService(Context.WINDOW_SERVICE);view=LayoutInflater.from(context).inflate(R.layout.overlay_bedtime,null);WindowManager.LayoutParams p=new WindowManager.LayoutParams(WindowManager.LayoutParams.MATCH_PARENT,WindowManager.LayoutParams.MATCH_PARENT,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_FULLSCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.START;wm.addView(view,p);} public static synchronized void hide(Context context){if(view==null)return;try{WindowManager wm=(WindowManager)context.getSystemService(Context.WINDOW_SERVICE);wm.removeView(view);}catch(Exception ignored){}view=null;} }
